Combining datasets

votes_count &lt;- proposals_votes |&gt; 
  filter(!is.na(vote)) |&gt;
  count(url, vote) |&gt; 
  tidyr::pivot_wider(names_from = vote, values_from = n) |&gt; 
  mutate(votes_total = rowSums(across(c(Approve, Oppose, Abstain, Other)), na.rm = TRUE)) |&gt; 
  rename(
    votes_approve = Approve,
    votes_oppose = Oppose,
    votes_abstain = Abstain,
    votes_other = Other
  )

proposals &lt;- proposals |&gt; 
  # Incorporate votes
  left_join(votes_count, by = join_by(fullurl == url))
